      <p>
        Email: 
        <a href="mailto:we4himcbo@gmail.com">
          we4himcbo@gmail.com
        </a>
      </p>
      <a href="tel:+254786115629">+254 786 115 629</a><br></br>
      <a href="tel:+254723142167">+254 723 142 167</a>
      <p>Migori County, Kenya</p>
    </footer>
  );
};

export default Footer;
